import {optimizedImageURL} from '../data/product-images.js';
import {contentFields,promotionFields,saveContent} from '../data/content.js';
import {aboutFields,aboutImages,homepageImages,editorialData,imageSource} from '../data/editorial.js';
import {validateImageFile} from './admin-gallery.js?v=tatnet-photos1';
import {uploadImage} from '../data/supabase.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderEditorialEditor(root,row,{about=false,promotions=false,preview,onDirty,onBusy,message}){
 const fields=promotions?promotionFields:about?aboutFields:contentFields.filter(f=>!f[0].startsWith('promo')),images=promotions?[]:about?aboutImages:homepageImages;
 const initial=editorialData(row?.data),pending=new Map();let key=fields[0][0],dirty=false,busy=false;
 root.innerHTML=`<div class="heading"><div><h1>${promotions?'Акции':about?'О нас':'Главная страница'}</h1><p class="count">Изменяйте тексты и фотографии. Проверьте результат справа и сохраните.</p></div></div><form class="panel content-form" id="content-form">${promotions?`<label class="promo-visibility"><input type="checkbox" id="promo-enabled" ${initial.promoEnabled!==false?'checked':''}> Показывать акцию на сайте и в меню</label>`:''}${fields.map(([field,label,,max])=>`<label>${esc(label)}<textarea name="${field}" maxlength="${max}" rows="${max>1000?5:3}">${esc(initial[field]||'')}</textarea></label>`).join('')}<section class="editorial-images" ${promotions?'hidden':''}><h2>${about?'Фотографии владельцев':'Фотографии главной страницы'}</h2><p class="hint">JPG, PNG или WebP, до 5 МБ. Новые фотографии загружаются только при сохранении.</p>${images.map(([field,label,,fallback])=>`<div class="editorial-image" data-image-field="${field}"><h3>${esc(label)}</h3><div class="editorial-image-preview"><img alt="${esc(label)}" hidden><span>Добавьте настоящую фотографию</span></div><label class="editorial-upload">Выбрать или заменить фото<input type="file" accept="image/jpeg,image/png,image/webp" data-upload-field="${field}" aria-label="${esc(label)}: выбрать фотографию"></label><button type="button" data-reset-field="${field}">${fallback?'Вернуть исходное фото':'Убрать фотографию'}</button><p class="hint" data-image-status></p></div>`).join('')}</section><div class="editorial-save"><p class="hint" role="status" id="editorial-status">Изменения ещё не внесены.</p><button class="primary">${promotions?'Сохранить акцию':about?'Сохранить страницу «О нас»':'Сохранить изменения'}</button></div></form>`;
 const form=root.querySelector('form');
 const draft=()=>{const data={...row?.data,...Object.fromEntries(new FormData(form))};if(promotions)data.promoEnabled=form.querySelector('#promo-enabled').checked;for(const [field,item]of pending)data[field]=item.preview||item.src||'';return data;};
 const update=()=>{const data=draft();for(const [field,, ,fallback]of images){const card=root.querySelector(`[data-image-field="${field}"]`),img=card.querySelector('img'),src=imageSource(data[field],true)||fallback;img.hidden=!src;card.querySelector('.editorial-image-preview span').hidden=!!src;if(src)img.src=optimizedImageURL(src,640);else img.removeAttribute('src');img.onerror=()=>{img.hidden=true;card.querySelector('.editorial-image-preview span').hidden=false;};card.querySelector('[data-reset-field]').disabled=busy||(!pending.has(field)&&!data[field]);}about?preview.updateAbout(data,key,dirty):preview.updateContent(data,key,dirty);};
 const changed=()=>{dirty=true;onDirty(true);root.querySelector('#editorial-status').textContent='Есть несохранённые изменения.';update();};

 form.addEventListener('input',event=>{if(event.target.matches('textarea,#promo-enabled'))changed();});
 form.addEventListener('focusin',event=>{key=event.target.name||event.target.dataset.uploadField||event.target.dataset.resetField||key;update();});
 form.addEventListener('change',event=>{const field=event.target.dataset.uploadField,file=event.target.files?.[0];if(!field||!file||busy)return;const card=event.target.closest('.editorial-image');try{validateImageFile(file);const old=pending.get(field);if(old?.preview)URL.revokeObjectURL(old.preview);pending.set(field,{file,preview:URL.createObjectURL(file)});key=field;card.querySelector('[data-image-status]').textContent='Новое фото выбрано. Сохраните изменения.';changed();}catch(error){card.querySelector('[data-image-status]').textContent=error.message;}finally{event.target.value='';}});
 form.addEventListener('click',event=>{const field=event.target.closest('[data-reset-field]')?.dataset.resetField;if(!field||busy)return;const old=pending.get(field);if(old?.preview)URL.revokeObjectURL(old.preview);pending.set(field,{src:''});key=field;root.querySelector(`[data-image-field="${field}"] [data-image-status]`).textContent='Изменение применится после сохранения.';changed();});
 form.onsubmit=async event=>{event.preventDefault();if(busy||!form.reportValidity())return;const data=draft();busy=true;onBusy(true);form.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=true);const status=root.querySelector('#editorial-status');status.textContent='Сохраняем…';
  try{for(const [field,item]of pending){if(item.file&&!item.src){status.textContent='Загружаем фотографии…';item.src=await uploadImage(item.file);}data[field]=item.src||'';}row=await saveContent(data,row);dirty=false;onDirty(false);for(const item of pending.values())if(item.preview)URL.revokeObjectURL(item.preview);pending.clear();status.textContent='Изменения сохранены.';root.querySelectorAll('[data-image-status]').forEach(el=>el.textContent='');message(promotions?'Акция сохранена.':about?'Страница «О нас» сохранена.':'Главная страница сохранена.');}
  catch(error){status.textContent=error.message;message(error.message);}
  finally{busy=false;onBusy(false);form.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=false);update();}
 };
 update();return ()=>{for(const item of pending.values())if(item.preview)URL.revokeObjectURL(item.preview);pending.clear();};
}
